#!/usr/bin/env python3
"""Norbury model endpoint and tool backends.

Root-only. Installed outside the learner project. It answers the model calls a
flow runtime makes and serves the three tool backends, keeping a per-run record
of the configuration it was handed and the tools it was offered, so a caller can
tell what a flow really did rather than what its JSON said it would.

Standard library only.
"""
import json
import os
import re
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, urlparse

PORT = int(os.environ.get("NORBURY_PORT", "8788"))
GRADER_KEY = "norbury-grader-nb6f"
GRADER_PREFIX = "/__nb6f"

# The placeholder a visual builder writes into an export where the key was.
EXPORT_PLACEHOLDER = "***"

TOOL_NAMES = ("arxiv_search", "web_search", "summarise")

# What each tool returns. Fixed text, so a briefing can be checked for the
# evidence that the tool actually ran.
TOOL_REPLIES = {
    "arxiv_search": ("arXiv:2411.00812 Sparse routing for long-context "
                     "retrieval; arXiv:2503.14477 Cache-aware decoding"),
    "web_search": ("Norbury Labs blog: retrieval routing in production; "
                   "Register piece on cache-aware decoding costs"),
    "summarise": ("Two threads dominate: routing sparsity and cache reuse."),
}

# The order a well-built research flow reaches for its tools.
TOOL_ORDER = ("arxiv_search", "web_search", "summarise")

_LOCK = threading.Lock()
_RUNS = {}


def _blank_run():
    return {"model_calls": 0, "tool_calls": [], "configs": [], "systems": [],
            "offered": [], "forced_finals": 0, "placeholder_seen": 0,
            "keys_seen": []}


def _run(run_id):
    return _RUNS.setdefault(run_id or "default", _blank_run())


def _last_user(messages):
    for message in reversed(messages or []):
        if (message.get("role") or "").lower() in ("user", "human"):
            return message.get("content") or ""
    return ""


def _tools_used(messages):
    """Which tools this conversation has already reported back from."""
    used = []
    for message in messages or []:
        if (message.get("role") or "").lower() in ("tool", "observation"):
            name = message.get("name") or ""
            if name and name not in used:
                used.append(name)
    return used


def _topic(text):
    cleaned = re.sub(r"^(research|tell me about|what about|look into)\s+", "",
                     (text or "").strip(), flags=re.I)
    return cleaned.strip(" .?").strip() or "the requested topic"


def decide(payload):
    """What the model does next, from the conversation and the tools offered."""
    messages = payload.get("messages") or []
    offered = [t for t in (payload.get("tools") or []) if t in TOOL_NAMES]
    used = _tools_used(messages)
    question = _last_user(messages)

    if payload.get("force_final"):
        return {"type": "final",
                "text": ("Wrapping up early. From what I gathered on %s: %s"
                         % (_topic(question), TOOL_REPLIES["arxiv_search"]))}

    # A question about what came earlier is answered from the conversation
    # itself, which is how a caller can tell whether memory was wired in.
    if re.search(r"what did i (ask|say)|earlier|before|first question",
                 question, re.I):
        earlier = [m.get("content") or "" for m in messages
                   if (m.get("role") or "").lower() in ("user", "human")]
        if len(earlier) >= 2:
            return {"type": "final",
                    "text": "Earlier you asked about %s." % _topic(earlier[0])}
        return {"type": "final",
                "text": "I have nothing earlier in this conversation to go on."}

    for name in TOOL_ORDER:
        if name in offered and name not in used:
            return {"type": "tool", "tool": name, "input": _topic(question)}

    findings = "; ".join(TOOL_REPLIES[name] for name in used) or "no sources"
    return {"type": "final",
            "text": "Briefing on %s. Findings: %s" % (_topic(question),
                                                      findings)}


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server_version = "norbury-flow/1.0"

    def log_message(self, *args):
        return

    def _send(self, code, payload):
        body = json.dumps(payload).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _body(self):
        length = int(self.headers.get("Content-Length") or 0)
        if not length:
            return {}
        try:
            return json.loads(self.rfile.read(length).decode())
        except Exception:
            return {}

    def _authorised(self):
        return self.headers.get("X-Grader-Key") == GRADER_KEY

    def do_GET(self):
        parsed = urlparse(self.path)
        query = parse_qs(parsed.query)
        if parsed.path == "/health":
            return self._send(200, {"ok": True, "service": "norbury-flow"})
        if parsed.path == "/v1/tools":
            return self._send(200, {"tools": list(TOOL_NAMES)})
        if parsed.path.startswith(GRADER_PREFIX):
            if not self._authorised():
                return self._send(404, {"error": "not found"})
            leaf = parsed.path[len(GRADER_PREFIX):]
            if leaf == "/trace":
                with _LOCK:
                    return self._send(200, dict(_run(query.get("run", [""])[0])))
            if leaf == "/replies":
                return self._send(200, {"tool_replies": dict(TOOL_REPLIES),
                                        "order": list(TOOL_ORDER)})
            return self._send(404, {"error": "not found"})
        return self._send(404, {"error": "not found"})

    def do_POST(self):
        parsed = urlparse(self.path)
        query = parse_qs(parsed.query)
        if parsed.path.startswith(GRADER_PREFIX):
            if not self._authorised():
                return self._send(404, {"error": "not found"})
            if parsed.path[len(GRADER_PREFIX):] == "/reset":
                run_id = query.get("run", [""])[0] or "default"
                with _LOCK:
                    _RUNS[run_id] = _blank_run()
                return self._send(200, {"reset": run_id})
            return self._send(404, {"error": "not found"})

        payload = self._body()
        run_id = payload.get("run_id") or os.environ.get("NORBURY_RUN_ID") \
            or "default"

        if parsed.path == "/v1/model":
            key = str(payload.get("api_key") or "")
            config = payload.get("config") or {}
            with _LOCK:
                record = _run(run_id)
                record["model_calls"] += 1
                record["configs"].append({
                    "model": config.get("model"),
                    "temperature": config.get("temperature"),
                })
                record["systems"].append((payload.get("system") or "")[:300])
                record["offered"].append(list(payload.get("tools") or []))
                record["keys_seen"].append(key[:40])
                if EXPORT_PLACEHOLDER and EXPORT_PLACEHOLDER in key:
                    record["placeholder_seen"] += 1
                if payload.get("force_final"):
                    record["forced_finals"] += 1
            if not key:
                return self._send(401, {"error": "no credential presented"})
            if EXPORT_PLACEHOLDER in key:
                return self._send(401, {
                    "error": "that is the placeholder a builder writes into an "
                             "export, not a credential"})
            return self._send(200, decide(payload))

        if parsed.path == "/v1/tool":
            name = payload.get("tool")
            if name not in TOOL_NAMES:
                return self._send(400, {"error": "unknown tool %r" % name})
            with _LOCK:
                record = _run(run_id)
                record["tool_calls"].append({
                    "tool": name,
                    "input": (payload.get("input") or "")[:120],
                    "max_results": payload.get("max_results"),
                })
            return self._send(200, {"tool": name, "text": TOOL_REPLIES[name]})

        return self._send(404, {"error": "not found"})


def main():
    server = ThreadingHTTPServer(("127.0.0.1", PORT), Handler)
    server.daemon_threads = True
    server.serve_forever()


if __name__ == "__main__":
    main()
___NBFILE___

chown -R root:root "$SVC"
chmod 700 "$SVC"
chmod 700 "${SVC}/flowsvc.py"
note "model endpoint files written (t+${SECONDS}s)"

echo "=== [5/8] Learner state the checks touch ==="
# A check runs the learner command line from inside the project, and that
# command WRITES a run log under runs/. If a check creates that directory first
# it is root-owned and the learner cannot write there afterwards. It is created
# here as the learner; the checks additionally chown the project back from an
# EXIT trap.
RUNS_DIR="${PROJ}/runs"
mkdir -p "$RUNS_DIR" 2>/dev/null || true
run "chown run log directory to ${LAB_USER}" chown -R "${LAB_USER}:${LAB_USER}" "$RUNS_DIR"
chmod 775 "$RUNS_DIR" 2>/dev/null || true
[ -d "$RUNS_DIR" ] && ok "run log directory pre-created and owned by ${LAB_USER}" \
    || warn "could not pre-create ${RUNS_DIR}"

# The credential a production runtime reads. The exports carry a placeholder
# where a key would be, and the learner needs a real one in the environment.
if [ ! -f /etc/profile.d/norbury.sh ]; then
    printf 'export NORBURY_API_KEY=nb-dev-%s\n' "$(date +%%s 2>/dev/null || echo 0)" \
        > /etc/profile.d/norbury.sh 2>/dev/null \
        && chmod 644 /etc/profile.d/norbury.sh 2>/dev/null \
        && ok "wrote /etc/profile.d/norbury.sh" \
        || warn "could not write the credential into the environment"
fi
note "learner state done (t+${SECONDS}s)"

echo "=== [6/8] Starting the model endpoint ==="
start_with_systemd() {
    command -v systemctl >/dev/null 2>&1 || return 1
    cat > /etc/systemd/system/norbury-desk.service <<UNIT
[Unit]
Description=Norbury flow model endpoint
After=network.target

[Service]
Type=simple
Environment=NORBURY_PORT=${PORT}
ExecStart=${PYBIN} ${SVC}/flowsvc.py
Restart=always
RestartSec=2
User=root

[Install]
WantedBy=multi-user.target
UNIT
    cap 15 systemctl daemon-reload >/dev/null 2>&1 || return 1
    cap 25 systemctl enable --now norbury-desk >/dev/null 2>&1 || return 1
    return 0
}

start_with_nohup() {
    if command -v systemctl >/dev/null 2>&1; then
        cap 15 systemctl disable --now norbury-desk >/dev/null 2>&1 || true
    fi
    export NORBURY_PORT="$PORT"
    detach /var/log/norbury-desk.log "$PYBIN" "${SVC}/flowsvc.py"
}

wait_health() {
    local i
    for i in $(seq 1 20); do
        svc_healthy && return 0
        sleep 0.5
    done
    return 1
}

if svc_healthy; then
    ok "model endpoint already running on ${PORT}"
elif start_with_systemd && wait_health; then
    ok "model endpoint started under systemd"
else
    echo "systemd path unavailable, falling back to a background process"
    start_with_nohup
    wait_health || warn "the model endpoint did not come up during setup; the check scripts start it on demand, so grading still works (see ${LOG})"
fi
if svc_healthy; then
    ok "model endpoint healthy on 127.0.0.1:${PORT}"
else
    warn "model endpoint not answering on 127.0.0.1:${PORT} at end of setup"
fi
note "model endpoint up (t+${SECONDS}s)"

echo "=== [7/8] Tooling hand-off ==="
DEPS_GRACE="${DEPS_GRACE:-5}"
for _i in $(seq 1 "$DEPS_GRACE"); do
    [ -f "$DEPS_READY" ] && break
    sleep 1
done
case "$(cat "$DEPS_STATE" 2>/dev/null)" in
    present) ok "curl and jq are installed" ;;
    missing) warn "curl or jq is missing - the check scripts need both (see ${DEPSLOG})" ;;
    *)       note "the grader tools are still installing in the background (log ${DEPSLOG}); the project and the model endpoint are ready now" ;;
esac
tail -n 5 "$DEPSLOG" 2>/dev/null | sed 's/^/    deps| /'
note "tooling handed off (t+${SECONDS}s)"

finish_summary() {
    [ "${SUMMARY_DONE:-0}" -eq 1 ] && return 0
    SUMMARY_DONE=1
    local blockers=""
    command -v python3 >/dev/null 2>&1 || blockers="${blockers} python3-missing"
    [ -s "${PROJ}/flowctl.py" ] || blockers="${blockers} project-missing"
    [ -s "${KIT}/__init__.py" ] || blockers="${blockers} kit-missing"
    svc_healthy || blockers="${blockers} desk-down"
    if [ -n "$blockers" ]; then
        warn "LAB NOT READY -${blockers}"
        note "provisioning could not finish the essentials. Re-running setup on a fresh VM is"
        note "the fastest remedy; the phase timings above show which step ran out of time."
        note "total setup time: ${SECONDS}s"
        return 0
    fi
cat <<SUMMARY

--------------------------------------------------------------------
Norbury flow lab is ready.

Project:   ${PROJ}
Provided:  flow_kit/         the model endpoint and the three tool backends
                            - do not modify
           flows/           two exports from the visual builder
           runs/            where your run logs go
           check_local.py   validates and runs the flows above
You write: flow/spec.py
           flow/runtime.py
           flowctl.py

The model endpoint is answering on http://127.0.0.1:${PORT}. Leave it running.
Everything here is the standard library - there is nothing to install.
NORBURY_API_KEY is already in your environment; open a new shell if it is not.

Verify your work with:
    cd ${PROJ} && python3 check_local.py

Setup log:    ${LOG}
Setup status: ${STATUS_FILE}
--------------------------------------------------------------------
SUMMARY

if [ "$WARNINGS" -gt 0 ]; then
    note "setup finished with ${WARNINGS} warning(s):"
    grep '^WARN' "$STATUS_FILE" 2>/dev/null | sed 's/^/    /'
else
    note "setup finished with no warnings"
fi
note "total setup time: ${SECONDS}s"
    if [ "$DEADLINE_HIT" -eq 1 ]; then
        note "finished early on the internal deadline; the project and the model endpoint are in place"
    fi
}

echo "=== [8/8] Permissions and summary ==="
run "chown project to ${LAB_USER}" chown -R "${LAB_USER}:${LAB_USER}" "$PROJ"
run "make project writable" chmod -R u+rw "$PROJ"
find "$PROJ" -type d -exec chmod u+x {} + 2>/dev/null || warn "could not set directory execute bits"
rm -rf "${PROJ}/__pycache__" "${KIT}/__pycache__" "${FLOWPKG}/__pycache__" 2>/dev/null || true
[ -w "${FLOWPKG}/spec.py" ] || warn "flow/spec.py is not writable - the learner will hit a read-only file"

finish_summary

kill "$WATCHDOG_PID" >/dev/null 2>&1 || true
sync 2>/dev/null || true
exit 0
